list_currencies.code:
use WebCommander\Resources\Currencies\Currencies;

$response = Currencies::listCurrencies($client, ['search' => 'dollar', 'active' => true]);

foreach ($response->map['currencies'] as $currency) {
    echo $currency['id'], ' ', $currency['code'], ' ', $currency['name'], ' ', $currency['conversion_rate'], $currency['base'] ? ' (base)' : '', PHP_EOL;
}
echo $response->map['pagination']['has_next'] ? 'more pages' : 'last page', PHP_EOL;

create_currency.code:
use WebCommander\Resources\Currencies\Currencies;

$response = Currencies::createCurrency($client, [
    'name' => 'Example Dollar', 'code' => 'XEX', 'symbol' => '$', 'country' => 'NZ',
    'conversion_rate' => 1.2345, 'precision' => 2, 'rounding' => 'nearest', 'active' => true,
], transactionNo: 'TXN-IMPORT-0001');

$currency = $response->map['currency'];
echo $currency['id'], ' ', $currency['code'], ' ', $currency['country']['name'], PHP_EOL;

update_currency.code:
use WebCommander\Resources\Currencies\Currencies;

$response = Currencies::updateCurrency($client, 1234, [
    'name' => 'Example Dollar', 'code' => 'XEX', 'symbol' => '$', 'country' => ['code' => 'US'],
    'conversion_rate' => 1.5, 'precision' => 3, 'rounding' => 'up', 'active' => false,
]);

$currency = $response->map['currency'];
echo $currency['conversion_rate'], ' ', $currency['rounding'], ' ', $currency['active'] ? 'active' : 'inactive', PHP_EOL;

set_base_currency.code:
use WebCommander\Resources\Currencies\Currencies;

$response = Currencies::setBaseCurrency($client, 1234);

echo $response->map['currency']['code'], ' is the base currency', PHP_EOL;
$previous = $response->map['previous_base'];
echo $previous === null ? 'it was already the base' : 'it replaced ' . $previous['code'], PHP_EOL;
